package com.lenid.accountlab;
import android.content.*;import java.io.*;import java.net.*;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;import org.json.*;
public final class LabHttp {
 final SSLSocketFactory tls;final String origin;final boolean test;
 public static void emulatorOnly()throws Exception{if(!"1".equals(Class.forName("android.os.SystemProperties").getMethod("get",String.class).invoke(null,"ro.kernel.qemu")))throw new SecurityException("Только тестовый эмулятор");}
 static byte[] bytes(InputStream in)throws Exception{if(in==null)throw new IOException("Пустой ответ");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>6000000)throw new IOException("Слишком большой ответ");}return out.toByteArray();}
 public static JSONObject validate(String s)throws Exception{return new JSONObject(s);}
 public LabHttp(Context context)throws Exception{JSONObject config;try(InputStream in=context.getAssets().open("service.json")){config=new JSONObject(new String(bytes(in),"UTF-8"));}origin=config.getString("origin");URL u=new URL(origin);test=config.optBoolean("test",false);if(!u.getProtocol().equals("https")||!u.getPath().isEmpty()||u.getUserInfo()!=null||u.getQuery()!=null||u.getRef()!=null)throw new IOException("Ошибка конфигурации сборки");if(test){KeyStore ks=KeyStore.getInstance(KeyStore.getDefaultType());ks.load(null,null);ks.setCertificateEntry("test",CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(config.getString("certificate_pem").getBytes("UTF-8"))));TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(ks);SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,tm.getTrustManagers(),null);tls=ssl.getSocketFactory();}else{if(u.getHost().matches("[0-9.]+")||u.getHost().equals("localhost"))throw new IOException("Для выпуска нужен адрес сервиса");tls=(SSLSocketFactory)SSLSocketFactory.getDefault();}SharedPreferences p=context.getSharedPreferences("phone",0);if(!origin.equals(p.getString("service_origin",""))){p.edit().remove("access").remove("refresh").remove("verified_profile").remove("photo_uri").remove("photo_id").remove("last_vehicle").putString("service_origin",origin).commit();}}
 public static class Failure extends IOException{public final int status;public final String code;Failure(int s,String c){super(c);status=s;code=c;}}
 public JSONObject call(int port,String method,String path,JSONObject body,String token)throws Exception{return call(method,path,body,token,null);}
 public JSONObject call(String method,String path,JSONObject body,String token,JSONObject headers)throws Exception{if(!path.startsWith("/v1/")||path.contains(".."))throw new IOException("Неверный адрес API");HttpsURLConnection c=(HttpsURLConnection)new URL(origin+path).openConnection(Proxy.NO_PROXY);c.setSSLSocketFactory(tls);c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(25000);c.setRequestMethod(method);c.setRequestProperty("Content-Type","application/json");if(token!=null&&!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(headers!=null){java.util.Iterator<String> keys=headers.keys();while(keys.hasNext()){String k=keys.next();c.setRequestProperty(k,headers.getString(k));}}try{if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int status=c.getResponseCode();JSONObject result;try(InputStream in=status>=400?c.getErrorStream():c.getInputStream()){result=new JSONObject(new String(bytes(in),"UTF-8"));}if(status!=200)throw new Failure(status,result.optString("error","HTTP "+status));return result;}finally{c.disconnect();}}
}
